import type { ComponentProps, ReactNode } from "react";

const cx = (...c: (string | false | null | undefined)[]) => c.filter(Boolean).join(" ");
export { cx };

const BTN = {
  primary: "bg-brand text-white hover:bg-brand-deep",
  quiet: "bg-white text-ink ring-1 ring-line hover:bg-paper",
  danger: "bg-white text-rose ring-1 ring-rose/40 hover:bg-rose-soft",
  mint: "bg-mint text-white hover:brightness-95",
};

export function Button({ variant = "primary", className, ...p }: ComponentProps<"button"> & { variant?: keyof typeof BTN }) {
  return (
    <button
      {...p}
      className={cx("inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-4 text-[15px] font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-50", BTN[variant], className)}
    />
  );
}

export const inputClass =
  "block w-full min-h-11 rounded-xl border border-line bg-white px-3 text-[15px] text-ink placeholder:text-muted/70 focus:border-brand focus:outline-none focus:ring-2 focus:ring-sky/40";

export function Field({ label, hint, children, className }: { label: string; hint?: string; children: ReactNode; className?: string }) {
  return (
    <label className={cx("block", className)}>
      <span className="mb-1 block text-sm font-semibold text-ink-soft">{label}</span>
      {children}
      {hint ? <span className="mt-1 block text-[13px] text-muted">{hint}</span> : null}
    </label>
  );
}

export function Notice({ tone = "info", children }: { tone?: "info" | "error" | "ok" | "warn"; children: ReactNode }) {
  const tones = { info: "bg-white ring-line text-ink-soft", error: "bg-rose-soft ring-rose/30 text-rose", ok: "bg-mint-soft ring-mint/40 text-ink", warn: "bg-amber-soft ring-amber/30 text-amber" };
  return <div role={tone === "error" ? "alert" : "status"} className={cx("rounded-xl px-4 py-3 text-[15px] ring-1", tones[tone])}>{children}</div>;
}

export const STATUS_LABEL: Record<string, string> = {
  pending: "Tentative", confirmed: "Confirmed", checked_in: "Arrived", completed: "Completed", cancelled: "Cancelled", no_show: "No-show",
};
const STATUS_TONE: Record<string, string> = {
  pending: "bg-amber-soft text-amber", confirmed: "bg-[#e3edff] text-brand-deep", checked_in: "bg-mint-soft text-[#087a5d]",
  completed: "bg-paper text-ink-soft ring-1 ring-line", cancelled: "bg-rose-soft text-rose", no_show: "bg-rose-soft text-rose",
};
export function StatusBadge({ status }: { status: string }) {
  return <span className={cx("inline-flex items-center rounded-full px-2.5 py-0.5 text-[13px] font-semibold whitespace-nowrap", STATUS_TONE[status] ?? "bg-paper")}>{STATUS_LABEL[status] ?? status}</span>;
}

const SOURCE_LABEL: Record<string, string> = { ai: "Assistant", web: "Booking form", staff: "Staff" };
export function SourceTag({ source }: { source: string }) {
  return <span className="text-[13px] text-muted">{SOURCE_LABEL[source] ?? source}</span>;
}

export function Card({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cx("overflow-hidden rounded-2xl bg-surface ring-1 ring-line", className)}>{children}</div>;
}

export function Logo({ size = 36 }: { size?: number }) {
  // eslint-disable-next-line @next/next/no-img-element
  return <img src="/logo-192.png" alt="" width={size} height={size} className="shrink-0" />;
}
